// Every SplitContainer capability, in the order the declaring class takes them.
template <typename Declaring>
struct SplitContainerCapabilities : public SplitContainerOrientationCapability<Declaring>,
                                    public SplitContainerSplitterDistanceCapability<Declaring>,
                                    public SplitContainerSplitterWidthCapability<Declaring>,
                                    public SplitContainerSplitterHitWidthCapability<Declaring>,
                                    public SplitContainerSplitterGeometryCapability<Declaring>,
                                    public SplitContainerSplitterTransitionDurationCapability<Declaring>,
                                    public SplitContainerFirstMinimumCapability<Declaring>,
                                    public SplitContainerSecondMinimumCapability<Declaring>,
                                    public SplitContainerFirstMaximumCapability<Declaring>,
                                    public SplitContainerSecondMaximumCapability<Declaring>,
                                    public SplitContainerSplitterFixedCapability<Declaring>,
                                    public SplitContainerFixedPanelCapability<Declaring>,
                                    public SplitContainerCollapsePanelCapability<Declaring>,
                                    public SplitContainerAutomaticCollapseThresholdCapability<Declaring>,
                                    public SplitContainerKeyboardIncrementCapability<Declaring> {};

